"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[5096],{5096:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-salvation-of-the-saint.png\\"\\n          title=\\"성녀의 구제\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"재인\\"\\n          publishedDate=\\"2009-12-28\\"\\n          isbn=\\"9788990982360\\"\\n          rating=4.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n```탐정 갈릴레오```의 두 번째 장편으로, 미스터리의 가장 고전적인 명제인 <mark>어떻게 죽였는가</mark>에 더욱 집중한 작품이다.  \\n<br>\\n이 작품을 관통하는 두 개의 핵심 열쇠는 바로 <mark>허수해</mark>와 <mark>구제</mark>라는 개념이다.  \\n<mark>허수해</mark>는 ```이론적으로는 가능하지만 현실에서는 결코 존재할 수 없는 해법```, 즉 완전범죄를 상징한다.  \\n반면, <mark>구제</mark>는 목숨을 살려두는 자비로운 행위인 동시에, 확실하게 단죄하기 위한 냉혹한 준비 과정이라는 모순적 의미를 품고 있다.  \\n<br>\\n죽이기 위한 노력보다는 ```죽이지 않기 위한 노력```이라는 점이 이 장르의 관습을 뒤흔드는 작품인 것 같다.  \\n<br>\\n진실이라는 하나의 목표를 향해 각기 다른 방식으로 접근하는 인물들이 존재한다.  \\n<br>\\n개인적으로 대담하고 기발한 트릭 중 하나이지 않을까 생각된다."}')}}]);